package com.bank.trademgmt.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "accounts")
public class Account {

    @Id
    @Column(name = "account_id")
    private String accountId;

    @Column(name = "holder_name")
    private String holderName;

    private BigDecimal balance;

    // INVERSE SIDE: "Trade.account field owns this relationship"
    @OneToMany(mappedBy = "account", cascade = CascadeType.ALL, orphanRemoval = true,
               fetch = FetchType.LAZY)
    private List<Trade> trades = new ArrayList<>();

    protected Account() {}

    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }

    // ═══ HELPER METHODS — synchronize BOTH sides ═══
    public void addTrade(Trade trade) {
        trades.add(trade);
        trade.setAccount(this);  // SET OWNING SIDE!
    }

    public void removeTrade(Trade trade) {
        trades.remove(trade);
        trade.setAccount(null);  // CLEAR OWNING SIDE!
        // orphanRemoval=true → JPA deletes this trade from DB
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public List<Trade> getTrades() { return trades; }
}
