package com.bank.trademgmt.service;

import com.bank.trademgmt.dto.TradeRequest;
import com.bank.trademgmt.model.*;
import com.bank.trademgmt.repository.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class TradeManagementService {

    private final AccountRepository accountRepo;

    @Transactional
    public Account addTradeToAccount(TradeRequest request) {
        Account account = accountRepo.findWithTrades(request.accountId())
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + request.accountId()));

        Trade trade = new Trade(request.tradeId(), request.symbol(), request.amount());

        // ═══ USE HELPER METHOD — sets BOTH sides ═══
        account.addTrade(trade);
        // Internally: trades.add(trade) + trade.setAccount(this)
        // cascade=ALL → JPA persists the new trade automatically on flush

        log.info("Added trade {} to account {} ({} total trades)",
            trade.getTradeId(), account.getAccountId(), account.getTrades().size());

        return account;  // cascade persists trade on transaction commit
    }

    @Transactional(readOnly = true)
    public Account getAccountWithTrades(String accountId) {
        return accountRepo.findWithTrades(accountId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + accountId));
    }
}
```

