package com.bank.trademgmt.controller;

import com.bank.trademgmt.dto.TradeRequest;
import com.bank.trademgmt.model.Account;
import com.bank.trademgmt.service.TradeManagementService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/trades")
@RequiredArgsConstructor
public class TradeController {

    private final TradeManagementService service;

    @PostMapping
    public String addTrade(@RequestBody TradeRequest request) {
        Account account = service.addTradeToAccount(request);
        return "Trade " + request.tradeId() + " added to " + account.getAccountId()
            + " (total: " + account.getTrades().size() + " trades)";
    }

    @GetMapping("/account/{accountId}")
    public Account getWithTrades(@PathVariable String accountId) {
        return service.getAccountWithTrades(accountId);
    }
}
