// ─── File: src/test/java/com/bank/trademgmt/service/RelationshipTest.java ───
package com.bank.trademgmt.service;

import com.bank.trademgmt.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class RelationshipTest {

    @Test
    void helperMethodSetsBothSides() {
        Account account = new Account("SAV2001", "Rajesh", BigDecimal.ZERO);
        Trade trade = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"));

        account.addTrade(trade);

        assertThat(account.getTrades()).contains(trade);    // inverse side set (Recommended) 
        assertThat(trade.getAccount()).isSameAs(account);   // owning side set (Recommended) 
    }

    @Test
    void removeHelperClearsBothSides() {
        Account account = new Account("SAV2001", "Rajesh", BigDecimal.ZERO);
        Trade trade = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"));
        account.addTrade(trade);

        account.removeTrade(trade);

        assertThat(account.getTrades()).isEmpty();           // inverse side cleared (Recommended) 
        assertThat(trade.getAccount()).isNull();              // owning side cleared (Recommended) 
    }

    @Test
    void settingOnlyInverseSideDoesNotSetFk() {
        Account account = new Account("SAV2001", "Rajesh", BigDecimal.ZERO);
        Trade trade = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"));

        // (Avoid) WRONG: only inverse side set
        account.getTrades().add(trade);
        // trade.getAccount() is still NULL! FK would be NULL in INSERT!
        assertThat(trade.getAccount()).isNull();  // owning side NOT set!
    }
}
```

sections.s5b_flow:
```
  ═══ DATABASE TABLES ═══

  accounts                          trades
  ┌──────────────┐                  ┌──────────────────────┐
  │ account_id PK│◄────FK──────────│ account_id FK (NOT NULL)│
  │ holder_name  │                  │ trade_id PK            │
  │ balance      │                  │ symbol                 │
  └──────────────┘                  │ amount                 │
                                    └──────────────────────┘

  ═══ JAVA ENTITY MAPPING ═══

  Account (PARENT — inverse side):
    @OneToMany(mappedBy = "account", cascade = ALL, orphanRemoval = true)
    List<Trade> trades;
    // mappedBy = "account" → "Trade.account owns the FK"

  Trade (CHILD — owning side):
    @ManyToOne(fetch = LAZY)
    @JoinColumn(name = "account_id", nullable = false)
    Account account;
    // This entity's table HAS the FK column → owning side

  ═══ HELPER METHOD — CRITICAL ═══

  account.addTrade(trade):
    trades.add(trade);          ← inverse side (navigation)
    trade.setAccount(this);     ← owning side (controls FK!)
  // BOTH sides must be set! JPA only reads the OWNING side for SQL generation.
```
